/**
 * Shared API contract types.
 *
 * These mirror the Rust structs in `apps/api/src/domain`. Phase 1 will replace the
 * hand-written section with types generated by `ts-rs` into `./generated` — keep the
 * field names identical to the Rust serialisation so the switch is mechanical.
 */

export type Role = "user" | "app_admin" | "super_admin";

export interface SessionUser {
  id: string;
  email: string;
  name: string;
  department: string | null;
  role: Role;
  /** Limits an `app_admin` to a set of app categories; absent for other roles. */
  adminScope: { categories?: string[] } | null;
  mustChangePassword: boolean;
}

export interface LoginResponse {
  token: string;
  expiresAt: string;
  user: SessionUser;
  mustChangePassword: boolean;
}

export interface Announcement {
  text: string;
  level: "info" | "warning" | "critical";
  /** ISO-8601 window; absent or null means always visible. */
  activeFrom?: string | null;
  activeTo?: string | null;
}

export interface AppTile {
  id: string;
  name: string;
  url: string;
  description: string | null;
  category: string | null;
  color: string | null;
  sortOrder: number;
  offlineVisible: boolean;
  iconUrl: string | null;
  iconEtag: string | null;
  updatedAt: string;
}

export interface SyncPayload {
  revision: number;
  serverTime: string;
  offlineValidUntil: string;
  snapshotDays: number;
  announcement: Announcement | null;
  user: Pick<SessionUser, "name" | "department" | "mustChangePassword">;
  apps: AppTile[];
}

export interface ApiError {
  error: {
    code: string;
    message: string;
  };
}

export interface HealthResponse {
  status: "ok";
  version: string;
  appName: string;
}
